-- 16. 칼럼 2편 추가 — 샘플 요청(바이어) / 첫 회신(공급사)
--     실행: node db.js supabase/16_columns_2.sql   (재실행 안전)
--     골격은 15_column_quote.sql 과 동일하다.
-- ============================================================

-- ---------- c-sample : 샘플을 요청하기 전에, 무엇을 정해두어야 할까? ----------
insert into columns_post (id, cat, date, img, title, excerpt, body, slug, seo_title, seo_desc, published)
values ('c-sample', $json${"ko":"가이드","vi":"Hướng dẫn","en":"Guide"}$json$::jsonb, '2026-08-04', 'assets/img/columns/sample-request.svg',
  $json${"ko":"샘플을 요청하기 전에, 무엇을 정해두어야 할까?","vi":"Trước khi xin hàng mẫu, cần quyết những gì?","en":"What to settle before you ask for samples"}$json$::jsonb, $json${"ko":"샘플은 받는 것보다 무엇을 볼지 정해두고 받는 것이 중요합니다. 요청 전에 정할 여섯 가지와 받은 뒤 남겨야 할 기록을 정리했습니다.","vi":"Quan trọng không phải là nhận được mẫu, mà là biết mình sẽ kiểm tra gì trước khi nhận. Bài này tóm tắt sáu việc cần quyết trước và những gì phải ghi lại sau khi nhận.","en":"What matters is not receiving a sample but knowing what you will check before it arrives. Six things to settle first, and what to record afterwards."}$json$::jsonb, $json${"ko":"<p>안녕하세요, 메이크노브입니다. 샘플은 받아보는 것보다, 무엇을 볼지 정해두고 받는 것이 중요합니다. 기준 없이 받으면 대개 \"괜찮네요\"에서 대화가 멈춥니다.</p>\n\n<h2>샘플까지 받고도 흐지부지되는 이유는 무엇일까?</h2>\n<p>받기 전에 확인 항목을 정하지 않았기 때문입니다. 무엇을 보려고 받는지가 없으면 결국 한두 사람의 인상만 남고, 사내에서 다음 단계를 설득할 근거가 되지 않습니다.</p>\n<p>공급사 쪽도 마찬가지입니다. \"샘플 보내주세요\"만 받으면 어느 규격으로, 어떤 포장으로, 라벨은 어느 언어로 보낼지 알 수 없습니다. 결국 되묻게 되고 일정이 밀립니다.</p>\n\n<h2>샘플을 요청하기 전에 정해둘 것은?</h2>\n<p>여섯 가지면 충분합니다. 이것만 정리해서 보내면 대부분 한 번에 진행됩니다.</p>\n<table>\n<tr><th>확인 항목</th><td>무엇을 보려고 받는지. 향과 발림성인지, 포장 강도인지, 표기 사항인지.</td></tr>\n<tr><th>수량</th><td>몇 개가 필요한지. 내부 검토용과 매장 반응 테스트용은 수량이 다릅니다.</td></tr>\n<tr><th>규격</th><td>판매용 완제품인지 벌크인지, 라벨을 현지어로 볼 것인지.</td></tr>\n<tr><th>비용 부담</th><td>샘플비와 배송비를 누가 낼지, 본 발주 시 차감이 되는지.</td></tr>\n<tr><th>기한</th><td>언제까지 받아야 하는지. 내부 회의 날짜가 있으면 그 날짜를 적습니다.</td></tr>\n<tr><th>함께 받을 자료</th><td>전성분표, 시험성적서, 인증서 사본 등.</td></tr>\n</table>\n<p>여기까지 정해두면 샘플이 도착했을 때 볼 것이 이미 정해져 있습니다. 판단이 빨라집니다.</p>\n\n<h2>샘플 비용은 누가 내는 것이 맞을까?</h2>\n<p>정해진 규칙은 없습니다. 다만 <strong>샘플비는 공급사, 국제 배송비는 바이어</strong>가 부담하는 형태가 가장 흔합니다. 배송비는 목적지와 무게에 따라 달라져서 공급사가 미리 떠안기 어렵기 때문입니다.</p>\n<p>무료를 먼저 요구하기보다 조건을 제시하는 편이 빠릅니다. \"샘플비는 지불하겠습니다. 본 발주가 성사되면 차감해 주실 수 있을까요?\" 이렇게 적으면 대부분 협의가 됩니다.</p>\n\n<h2>샘플을 받은 뒤에는 무엇을 남겨야 할까?</h2>\n<p>도착 날짜, 로트번호, 개봉 사진, 확인 항목별 결과를 남겨두세요. 나중에 본 발주 물량이 들어왔을 때 이 기록이 품질을 따지는 유일한 기준이 됩니다.</p>\n<p>문제가 있으면 구체적으로 알려야 합니다. \"품질이 별로다\"로는 아무것도 바뀌지 않습니다. 어느 부분이 어떻게 다른지 사진과 함께 보내면 대체 규격이나 다른 라인을 제안받을 수 있습니다.</p>\n<p>통과든 보류든 결론은 공급사에 알려주는 편이 좋습니다. 다음 거래가 훨씬 수월해집니다.</p>\n\n<h2>메이크노브는</h2>\n<p>전 세계 공급사의 혁신 제품을 한자리에 모아두고, 사업자 인증을 통과한 바이어에게 단가와 최소주문수량을 공개하는 B2B 플랫폼입니다. 샘플 요청은 견적 문의와 함께 공급사에 바로 전달됩니다.</p>\n<p>가입과 인증은 무료이고 1분 정도 걸립니다.</p>","vi":"<p>Xin chào, MAKENOV đây. Với hàng mẫu, việc nhận được không quan trọng bằng việc biết trước mình sẽ kiểm tra gì. Không có tiêu chí thì câu chuyện thường dừng ở một câu \"cũng được đấy\".</p>\n\n<h2>Vì sao nhận mẫu rồi mà mọi việc vẫn bỏ dở?</h2>\n<p>Vì trước khi nhận đã không định ra mục cần kiểm. Không biết nhận để xem gì thì cuối cùng chỉ còn lại cảm nhận của một hai người, không đủ làm căn cứ thuyết phục nội bộ đi tiếp.</p>\n<p>Phía nhà cung cấp cũng vậy. Chỉ nhận được câu \"gửi mẫu giúp tôi\" thì họ không biết gửi quy cách nào, đóng gói ra sao, nhãn bằng tiếng gì. Cuối cùng lại phải hỏi lại và lịch bị lùi.</p>\n\n<h2>Trước khi xin mẫu cần quyết những gì?</h2>\n<p>Sáu mục là đủ. Chỉ cần gửi đi bấy nhiêu, phần lớn trường hợp chạy được ngay một lần.</p>\n<table>\n<tr><th>Mục cần kiểm</th><td>Nhận để xem gì: mùi và độ thẩm thấu, độ bền bao bì, hay nội dung ghi nhãn.</td></tr>\n<tr><th>Số lượng</th><td>Cần bao nhiêu. Xem xét nội bộ và thử phản ứng tại cửa hàng là hai con số khác nhau.</td></tr>\n<tr><th>Quy cách</th><td>Hàng thành phẩm để bán hay hàng bulk, nhãn có cần tiếng bản địa không.</td></tr>\n<tr><th>Chi phí</th><td>Ai trả tiền mẫu và cước, có được trừ vào đơn chính thức không.</td></tr>\n<tr><th>Thời hạn</th><td>Cần nhận trước ngày nào. Có lịch họp nội bộ thì ghi đúng ngày đó.</td></tr>\n<tr><th>Hồ sơ kèm theo</th><td>Bảng thành phần, phiếu kiểm nghiệm, bản sao chứng nhận.</td></tr>\n</table>\n<p>Quyết xong đến đây thì lúc mẫu tới, việc cần xem đã có sẵn. Quyết định sẽ nhanh hơn.</p>\n\n<h2>Tiền mẫu ai trả là hợp lý?</h2>\n<p>Không có quy tắc cố định. Nhưng phổ biến nhất là <strong>nhà cung cấp chịu tiền mẫu, người mua chịu cước quốc tế</strong>. Cước thay đổi theo điểm đến và trọng lượng nên nhà cung cấp khó ôm trước.</p>\n<p>Đề xuất điều kiện sẽ nhanh hơn là đòi miễn phí ngay. \"Tôi sẽ trả tiền mẫu. Nếu đơn chính thức thành công thì trừ lại giúp tôi được không?\" — viết vậy thì phần lớn thương lượng được.</p>\n\n<h2>Sau khi nhận mẫu cần ghi lại gì?</h2>\n<p>Ghi ngày nhận, số lô, ảnh lúc mở hộp và kết quả theo từng mục đã định. Về sau khi hàng của đơn chính thức về, đây là căn cứ duy nhất để nói chuyện chất lượng.</p>\n<p>Có vấn đề thì phải nói cụ thể. \"Chất lượng không tốt\" thì không thay đổi được gì. Chỉ rõ chỗ nào khác ra sao kèm ảnh thì bạn có thể được đề xuất quy cách thay thế hoặc dòng hàng khác.</p>\n<p>Dù đạt hay tạm gác lại, nên báo kết luận cho nhà cung cấp. Lần giao dịch sau sẽ dễ hơn nhiều.</p>\n\n<h2>Về MAKENOV</h2>\n<p>MAKENOV là nền tảng B2B tập hợp sản phẩm đổi mới của các nhà cung cấp toàn cầu, và mở đơn giá cùng số lượng tối thiểu cho nhà mua đã xác thực doanh nghiệp. Yêu cầu hàng mẫu được chuyển thẳng tới nhà cung cấp cùng với yêu cầu báo giá.</p>\n<p>Đăng ký và xác thực miễn phí, mất khoảng một phút.</p>","en":"<p>Hello, this is MAKENOV. With samples, receiving one matters less than knowing what you will check before it arrives. Without criteria, the conversation usually stops at \"seems fine\".</p>\n\n<h2>Why do sample requests fizzle out?</h2>\n<p>Because nobody decided what to look at beforehand. If there is no stated purpose, all that remains is one or two people's impressions, which is not enough to justify the next step internally.</p>\n<p>It is the same on the supplier's side. \"Please send samples\" does not say which specification, what packaging, or which language on the label. They have to write back, and the schedule slips.</p>\n\n<h2>What should you settle before asking?</h2>\n<p>Six items are enough. Send these and most requests go through in one pass.</p>\n<table>\n<tr><th>What to check</th><td>The reason you want it: scent and texture, packaging strength, or label content.</td></tr>\n<tr><th>Quantity</th><td>How many. Internal review and an in-store response test are different numbers.</td></tr>\n<tr><th>Specification</th><td>Retail-ready or bulk, and whether you need the label in the local language.</td></tr>\n<tr><th>Who pays</th><td>Sample cost and freight, and whether it is deductible from the main order.</td></tr>\n<tr><th>Deadline</th><td>The date you need it by. If there is an internal meeting, use that date.</td></tr>\n<tr><th>Documents</th><td>Ingredient list, test reports, copies of certificates.</td></tr>\n</table>\n<p>Decide these and the moment the sample lands, you already know what to examine. The decision comes faster.</p>\n\n<h2>Who normally pays for samples?</h2>\n<p>There is no fixed rule, but the most common split is <strong>the supplier covers the sample, the buyer covers international freight</strong>. Freight varies by destination and weight, so suppliers are reluctant to absorb it up front.</p>\n<p>Proposing terms works better than asking for free. \"We will pay for the samples. Could that be credited against the main order if it goes ahead?\" — that usually opens a negotiation.</p>\n\n<h2>What should you record afterwards?</h2>\n<p>Record the arrival date, lot number, unboxing photos, and the result against each item you set. When the main shipment arrives later, this is the only basis you have for a quality discussion.</p>\n<p>If something is wrong, be specific. \"The quality is poor\" changes nothing. Point out what differs and how, with photos, and you may be offered an alternative specification or a different line.</p>\n<p>Pass or hold, tell the supplier your conclusion. The next deal goes far more smoothly.</p>\n\n<h2>About MAKENOV</h2>\n<p>MAKENOV is a B2B platform that gathers innovative products from suppliers worldwide and opens unit prices and minimum order quantities to buyers who pass business verification. Sample requests go straight to the supplier alongside your quote request.</p>\n<p>Signing up and verifying is free and takes about a minute.</p>"}$json$::jsonb,
  'sample-request-checklist', '수입 샘플 요청 체크리스트 — 수량·비용 부담·확인 항목', '샘플 요청이 흐지부지되는 이유, 요청 전에 정할 여섯 가지, 샘플비와 배송비 부담 관행, 받은 뒤 남겨야 할 기록까지 정리했습니다.', true)
on conflict (id) do update set
  cat=excluded.cat, date=excluded.date, img=excluded.img,
  title=excluded.title, excerpt=excluded.excerpt, body=excluded.body,
  slug=excluded.slug, seo_title=excluded.seo_title, seo_desc=excluded.seo_desc,
  published=true;

insert into faqs (id, page, sort, q, a, published)
values ('csf1', 'c-sample', 1, $json${"ko":"견적 없이 샘플만 먼저 요청해도 되나요?","vi":"Chưa cần báo giá, xin mẫu trước được không?","en":"Can I ask for samples before a quote?"}$json$::jsonb, $json${"ko":"됩니다. 다만 예상 수량과 필요 시기를 함께 적어주세요. 공급사가 어느 규격으로 보낼지 판단할 근거가 되고, 같은 회신에 단가까지 함께 받을 수 있습니다.","vi":"Được. Nhưng hãy ghi kèm số lượng dự kiến và thời điểm cần. Đó là căn cứ để nhà cung cấp chọn quy cách gửi, và bạn nhận luôn cả đơn giá trong cùng một hồi âm.","en":"Yes. Include your expected quantity and timing though — it tells the supplier which specification to send, and you get the price back in the same reply."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('csf2', 'c-sample', 2, $json${"ko":"샘플 비용은 보통 얼마인가요?","vi":"Tiền mẫu thường là bao nhiêu?","en":"How much do samples usually cost?"}$json$::jsonb, $json${"ko":"제품과 수량에 따라 달라서 일률적으로 말하기 어렵습니다. 견적을 요청할 때 샘플 조건을 함께 물어보시면 단가와 같이 안내받을 수 있습니다.","vi":"Tùy sản phẩm và số lượng nên khó nói chung. Khi gửi yêu cầu báo giá, hãy hỏi luôn điều kiện hàng mẫu để được báo cùng đơn giá.","en":"It varies by product and quantity, so there is no single answer. Ask about sample terms in your quote request and you will get both together."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('csf3', 'c-sample', 3, $json${"ko":"샘플 배송은 얼마나 걸리나요?","vi":"Gửi mẫu mất bao lâu?","en":"How long does sample delivery take?"}$json$::jsonb, $json${"ko":"국제 특송 기준으로 발송 후 3~7일이 일반적이지만, 통관 상황과 품목에 따라 더 걸릴 수 있습니다. 화장품과 식품은 성분 자료를 함께 보내야 통관이 수월합니다.","vi":"Chuyển phát nhanh quốc tế thường 3–7 ngày sau khi gửi, nhưng có thể lâu hơn tùy tình hình thông quan và mặt hàng. Mỹ phẩm và thực phẩm nên gửi kèm hồ sơ thành phần cho dễ thông quan.","en":"Typically three to seven days by international courier, though customs and the product category can add time. For cosmetics and food, sending the ingredient documents along makes clearance easier."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('csf4', 'c-sample', 4, $json${"ko":"샘플이 기대와 다르면 어떻게 하나요?","vi":"Mẫu không như mong đợi thì làm sao?","en":"What if the sample is not what I expected?"}$json$::jsonb, $json${"ko":"어느 부분이 어떻게 다른지 사진과 함께 알려주세요. 대체 규격이나 다른 라인을 제안받는 경우가 많습니다. 진행하지 않기로 했더라도 결론은 알려주는 편이 좋습니다.","vi":"Hãy nói rõ chỗ nào khác ra sao kèm ảnh. Nhiều trường hợp bạn sẽ được đề xuất quy cách thay thế hoặc dòng khác. Dù quyết định dừng, vẫn nên báo kết luận.","en":"Say what differs and how, with photos. Suppliers often propose an alternative specification or another line. Even if you decide not to proceed, it is worth telling them."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

-- ---------- c-reply : 해외 바이어 문의가 왔을 때, 무엇부터 답해야 할까? ----------
insert into columns_post (id, cat, date, img, title, excerpt, body, slug, seo_title, seo_desc, published)
values ('c-reply', $json${"ko":"공급사","vi":"Nhà cung cấp","en":"Suppliers"}$json$::jsonb, '2026-08-03', 'assets/img/columns/supplier-reply.svg',
  $json${"ko":"해외 바이어 문의가 왔을 때, 무엇부터 답해야 할까?","vi":"Khi có nhà mua nước ngoài hỏi, nên trả lời điều gì trước?","en":"An overseas buyer just enquired. What do you answer first?"}$json$::jsonb, $json${"ko":"첫 회신에 무엇을 담느냐로 다음 연락이 올지가 갈립니다. 길게 쓸 필요는 없고, 바이어가 결정하는 데 필요한 여섯 가지만 있으면 됩니다.","vi":"Hồi âm đầu tiên chứa gì sẽ quyết định có liên lạc tiếp hay không. Không cần viết dài, chỉ cần sáu mục mà người mua dùng để ra quyết định.","en":"What goes in the first reply decides whether there is a second one. It need not be long — just the six things the buyer needs to decide."}$json$::jsonb, $json${"ko":"<p>안녕하세요, 메이크노브입니다. 해외 바이어의 첫 문의에 무엇을 담아 답하느냐로 다음 연락이 올지가 갈립니다. 길게 쓸 필요는 없습니다. 바이어가 결정을 내리는 데 필요한 것만 있으면 됩니다.</p>\n\n<h2>회신이 늦으면 왜 불리할까?</h2>\n<p>바이어는 보통 같은 품목으로 여러 곳에 동시에 문의합니다. 먼저 도착한 회신의 조건이 기준이 되고, 뒤에 온 곳은 그 기준과 비교당하는 자리에서 시작합니다.</p>\n<p>완벽한 답을 만들다가 늦는 것보다, 확정된 것을 먼저 보내고 나머지는 언제까지 회신하겠다고 적는 편이 낫습니다. 답이 왔다는 사실 자체가 이미 판단 재료입니다.</p>\n\n<h2>첫 회신에 반드시 넣을 것은?</h2>\n<p>여섯 항목이면 충분합니다. 이것이 갖춰진 회신은 바로 내부 검토로 넘어갑니다.</p>\n<table>\n<tr><th>단가와 기준</th><td>FOB인지 CIF인지, 그리고 이 가격이 언제까지 유효한지.</td></tr>\n<tr><th>최소주문수량</th><td>수량 구간별 단가가 있으면 함께. 협의 여지가 있으면 그 사실도 적습니다.</td></tr>\n<tr><th>납기</th><td>발주 확정 후 며칠인지. 재고가 있으면 그것도 적습니다.</td></tr>\n<tr><th>결제 조건</th><td>T/T 선금 비율, 잔금 시점 등.</td></tr>\n<tr><th>보유 서류</th><td>전성분표, 시험성적서, 인증서 목록. 있는 것만 적습니다.</td></tr>\n<tr><th>담당자</th><td>이름, 직접 연락 가능한 수단, 연락 가능한 시간대.</td></tr>\n</table>\n<p>메이크노브를 통해 오는 문의에는 회사명, 담당자, 연락처, 요청 내용이 이미 정리되어 있습니다. 상대가 누구인지 확인한 뒤 회신하시면 됩니다.</p>\n\n<h2>아직 정해지지 않은 항목은 어떻게 적을까?</h2>\n<p>빈칸으로 두지 마세요. 빠진 항목은 바이어가 \"이 회사는 준비가 안 되어 있다\"로 읽습니다.</p>\n<p>대신 이렇게 적습니다. \"베트남향 라벨 제작 여부는 확인 중이며, 이번 주 금요일까지 회신드리겠습니다.\" 언제까지 답하겠다는 문장 하나가 빈칸을 대신합니다.</p>\n<p>확정되지 않은 숫자를 급하게 던지는 것이 가장 위험합니다. 나중에 조건이 달라지면 그때부터는 가격 문제가 아니라 신뢰 문제가 됩니다. 확실하지 않으면 범위로 적고 어떤 조건에서 그 범위가 정해지는지 함께 적으세요.</p>\n\n<h2>수출 경험이 없어도 문의를 받아도 될까?</h2>\n<p>됩니다. 첫 거래는 대부분 소량 테스트 오더로 시작합니다. 경험이 없다는 사실을 숨기지 말고, 지금 준비된 것과 아직 없는 것을 그대로 적는 편이 낫습니다.</p>\n<p>다만 <strong>수출 단가와 최소주문수량은 미리 정해두셔야</strong> 합니다. 바이어가 가장 먼저 묻는 두 가지이고, 이것이 없으면 문의가 와도 대화가 진행되지 않습니다.</p>\n<p>서류가 없다면 준비 기간을 함께 제시하면 됩니다. \"해당 시험성적서는 보유하고 있지 않으며, 발급까지 약 3주가 소요됩니다.\" 이렇게 적으면 바이어가 일정을 계산할 수 있습니다.</p>\n\n<h2>메이크노브는</h2>\n<p>메이크노브는 공급사의 제품을 해외 바이어에게 상시 노출하고, 사업자 인증을 통과한 바이어의 문의만 전달합니다. 상세페이지와 기업 프로필은 베트남어·영어·한국어로 저희가 제작합니다. 등록비는 받지 않고, 다른 채널과 병행하셔도 됩니다.</p>\n<p>제품 등록 문의는 회사와 제품만 남겨주시면 됩니다.</p>","vi":"<p>Xin chào, MAKENOV đây. Hồi âm đầu tiên cho yêu cầu của nhà mua nước ngoài chứa những gì sẽ quyết định có liên lạc tiếp hay không. Không cần viết dài, chỉ cần đủ những gì người mua dùng để ra quyết định.</p>\n\n<h2>Vì sao hồi âm chậm lại bất lợi?</h2>\n<p>Người mua thường hỏi nhiều nơi cùng lúc cho cùng một mặt hàng. Điều kiện của thư đến trước trở thành mốc, và những nơi trả lời sau bắt đầu ở thế bị đem ra so với mốc đó.</p>\n<p>Thay vì chuẩn bị một câu trả lời hoàn hảo rồi trễ, hãy gửi trước những gì đã chốt và ghi rõ khi nào sẽ trả lời phần còn lại. Bản thân việc có hồi âm đã là dữ liệu để họ đánh giá.</p>\n\n<h2>Thư trả lời đầu tiên phải có gì?</h2>\n<p>Sáu mục là đủ. Một hồi âm có đủ chừng đó sẽ được chuyển thẳng vào khâu xem xét nội bộ.</p>\n<table>\n<tr><th>Giá và điều kiện</th><td>FOB hay CIF, và giá này có hiệu lực đến khi nào.</td></tr>\n<tr><th>Số lượng tối thiểu</th><td>Có bậc giá theo số lượng thì ghi kèm. Có thể thương lượng thì nói rõ.</td></tr>\n<tr><th>Thời gian giao</th><td>Bao nhiêu ngày sau khi chốt đơn. Có sẵn hàng tồn thì ghi luôn.</td></tr>\n<tr><th>Điều kiện thanh toán</th><td>Tỷ lệ đặt cọc T/T, thời điểm thanh toán phần còn lại.</td></tr>\n<tr><th>Hồ sơ đang có</th><td>Bảng thành phần, phiếu kiểm nghiệm, danh mục chứng nhận. Chỉ ghi cái đang có.</td></tr>\n<tr><th>Người phụ trách</th><td>Tên, cách liên hệ trực tiếp, khung giờ liên lạc được.</td></tr>\n</table>\n<p>Yêu cầu đến qua MAKENOV đã có sẵn tên công ty, người phụ trách, liên hệ và nội dung yêu cầu. Bạn xem đối tác là ai rồi hồi âm.</p>\n\n<h2>Những mục chưa chốt thì ghi thế nào?</h2>\n<p>Đừng để trống. Mục bị bỏ trống sẽ được đọc thành \"công ty này chưa sẵn sàng\".</p>\n<p>Hãy viết thế này: \"Việc làm nhãn cho thị trường Việt Nam đang được xác nhận, chúng tôi sẽ phản hồi trước thứ Sáu tuần này.\" Một câu hẹn ngày thay được cho ô trống.</p>\n<p>Nguy hiểm nhất là vội đưa ra con số chưa chốt. Về sau điều kiện đổi thì đó không còn là chuyện giá mà thành chuyện tin cậy. Chưa chắc thì ghi theo khoảng và nói rõ khoảng đó phụ thuộc điều kiện nào.</p>\n\n<h2>Chưa có kinh nghiệm xuất khẩu thì có nên nhận không?</h2>\n<p>Nên. Giao dịch đầu phần lớn bắt đầu bằng đơn thử số lượng nhỏ. Đừng giấu việc chưa có kinh nghiệm, cứ ghi đúng những gì đã sẵn sàng và những gì chưa có.</p>\n<p>Nhưng <strong>giá xuất khẩu và số lượng tối thiểu thì phải định trước</strong>. Đó là hai câu người mua hỏi đầu tiên, thiếu chúng thì có yêu cầu tới cũng không đi tiếp được.</p>\n<p>Nếu chưa có hồ sơ, hãy đưa kèm thời gian chuẩn bị: \"Chúng tôi chưa có phiếu kiểm nghiệm này, thời gian cấp khoảng ba tuần.\" Viết vậy thì người mua tính được lịch.</p>\n\n<h2>Về MAKENOV</h2>\n<p>MAKENOV đưa sản phẩm của nhà cung cấp tiếp cận nhà mua nước ngoài liên tục, và chỉ chuyển những yêu cầu từ người mua đã xác thực doanh nghiệp. Trang chi tiết và hồ sơ công ty do chúng tôi biên soạn bằng tiếng Việt, tiếng Anh và tiếng Hàn. Không thu phí đăng ký, và bạn vẫn có thể bán song song qua kênh khác.</p>\n<p>Để đăng ký sản phẩm, bạn chỉ cần để lại tên công ty và sản phẩm.</p>","en":"<p>Hello, this is MAKENOV. What you put in the first reply to an overseas buyer decides whether a second message ever comes. It does not need to be long — only what the buyer needs in order to decide.</p>\n\n<h2>Why does a slow reply cost you?</h2>\n<p>Buyers usually enquire with several suppliers at once for the same item. The terms in the first reply become the benchmark, and everyone answering later starts out being compared against it.</p>\n<p>Rather than being late while assembling a perfect answer, send what is confirmed and state when the rest will follow. The fact that you replied at all is already information.</p>\n\n<h2>What must the first reply carry?</h2>\n<p>Six items are enough. A reply with these goes straight into internal review.</p>\n<table>\n<tr><th>Price and basis</th><td>FOB or CIF, and how long the price holds.</td></tr>\n<tr><th>Minimum order</th><td>Include volume tiers if you have them, and say so if there is room to negotiate.</td></tr>\n<tr><th>Lead time</th><td>Days from order confirmation. Mention stock on hand if there is any.</td></tr>\n<tr><th>Payment terms</th><td>T/T deposit percentage, when the balance falls due.</td></tr>\n<tr><th>Documents held</th><td>Ingredient list, test reports, certificates. List only what you actually have.</td></tr>\n<tr><th>Contact</th><td>Name, a direct channel, and the hours you can be reached.</td></tr>\n</table>\n<p>Enquiries arriving through MAKENOV already carry the company name, contact person, contact details and the request itself. Check who you are dealing with, then reply.</p>\n\n<h2>How do you write the parts that are not settled?</h2>\n<p>Do not leave them blank. A missing line reads as \"this company is not ready\".</p>\n<p>Write it out instead: \"Vietnamese labelling is being confirmed and we will come back to you by Friday.\" One sentence with a date does the work of the blank.</p>\n<p>The riskiest move is throwing out a number you have not confirmed. If the terms change later it stops being a pricing question and becomes a trust question. When unsure, give a range and say what determines where in that range it lands.</p>\n\n<h2>Can you take enquiries with no export experience?</h2>\n<p>Yes. First deals almost always start as small trial orders. Do not hide the lack of experience — write down what is ready and what is not.</p>\n<p>But <strong>you must have an export price and a minimum order quantity</strong> decided in advance. They are the first two things a buyer asks, and without them the conversation cannot move even when an enquiry arrives.</p>\n<p>If a document is missing, offer the lead time with it: \"We do not hold that test report; issuance takes about three weeks.\" That lets the buyer plan around it.</p>\n\n<h2>About MAKENOV</h2>\n<p>MAKENOV keeps supplier products in front of overseas buyers continuously and forwards only enquiries from buyers who have passed business verification. We produce the detail pages and company profiles in Vietnamese, English and Korean. There is no listing fee, and you may keep selling through other channels.</p>\n<p>To list a product, just leave your company and product details.</p>"}$json$::jsonb,
  'supplier-first-reply', '해외 바이어 문의 회신 작성법 — 첫 답장에 넣을 6가지', '회신이 늦으면 왜 불리한지, 첫 답장에 반드시 넣을 여섯 항목, 아직 정해지지 않은 조건을 적는 법, 수출 경험이 없을 때의 대응까지 정리했습니다.', true)
on conflict (id) do update set
  cat=excluded.cat, date=excluded.date, img=excluded.img,
  title=excluded.title, excerpt=excluded.excerpt, body=excluded.body,
  slug=excluded.slug, seo_title=excluded.seo_title, seo_desc=excluded.seo_desc,
  published=true;

insert into faqs (id, page, sort, q, a, published)
values ('crf1', 'c-reply', 1, $json${"ko":"회신은 어느 언어로 써야 하나요?","vi":"Nên hồi âm bằng ngôn ngữ nào?","en":"Which language should I reply in?"}$json$::jsonb, $json${"ko":"제품 상세페이지와 기업 프로필은 메이크노브가 베트남어·영어·한국어로 제작합니다. 문의 회신은 담당자가 직접 하시게 되며, 짧은 영어로 항목만 정리해 보내셔도 충분합니다.","vi":"Trang chi tiết sản phẩm và hồ sơ công ty do MAKENOV biên soạn bằng tiếng Việt, Anh, Hàn. Phần hồi âm do người phụ trách trực tiếp gửi, viết tiếng Anh ngắn gọn theo từng mục là đủ.","en":"MAKENOV produces the product pages and company profile in Vietnamese, English and Korean. Replies are sent by your own contact person, and short English laid out item by item is enough."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('crf2', 'c-reply', 2, $json${"ko":"단가를 공개하기가 부담스럽습니다.","vi":"Ngại công khai đơn giá thì sao?","en":"I would rather not publish my prices."}$json$::jsonb, $json${"ko":"가격·MOQ·납기는 기본적으로 가려져 있고 사업자 인증을 통과한 바이어에게만 열립니다. 그마저도 원치 않으시면 문의 시 안내로 표기할 수 있습니다.","vi":"Giá, MOQ và thời gian giao mặc định được ẩn, chỉ mở cho nhà mua đã xác thực doanh nghiệp. Nếu vẫn không muốn, có thể để là \"liên hệ để biết\".","en":"Price, MOQ and lead time are hidden by default and open only to verified buyers. If even that is too much, they can be shown as \"on request\"."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('crf3', 'c-reply', 3, $json${"ko":"문의는 어떤 형태로 전달되나요?","vi":"Yêu cầu được chuyển tới dưới dạng nào?","en":"In what form does an enquiry reach me?"}$json$::jsonb, $json${"ko":"회사명, 담당자, 연락처, 요청 내용이 정리된 형태로 전달됩니다. 전시회에서 받는 명함과 달리 상대가 어디 소속이고 무엇을 원하는지 확인한 뒤 회신하실 수 있습니다.","vi":"Được chuyển ở dạng đã sắp xếp gồm tên công ty, người phụ trách, liên hệ và nội dung yêu cầu. Khác với danh thiếp nhận ở hội chợ, bạn biết đối phương thuộc đâu và muốn gì rồi mới trả lời.","en":"As an organised record: company name, contact person, contact details and the request. Unlike a business card from a trade fair, you know who they are and what they want before replying."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

insert into faqs (id, page, sort, q, a, published)
values ('crf4', 'c-reply', 4, $json${"ko":"등록까지 얼마나 걸리나요?","vi":"Đăng ký mất bao lâu?","en":"How long does listing take?"}$json$::jsonb, $json${"ko":"자료를 모두 받은 시점부터 통상 영업일 5일 이내에 게시됩니다. 제품 수가 많거나 번역 분량이 큰 경우에는 일정을 미리 안내드립니다.","vi":"Thường trong vòng 5 ngày làm việc kể từ khi nhận đủ tài liệu. Nếu số lượng sản phẩm nhiều hoặc khối lượng dịch lớn, chúng tôi sẽ báo lịch trước.","en":"Usually within five business days of receiving all materials. If there are many products or a large volume to translate, we tell you the schedule in advance."}$json$::jsonb, true)
on conflict (id) do update set page=excluded.page, sort=excluded.sort,
  q=excluded.q, a=excluded.a, published=true;

